// app/lib/encryptionKey.ts
import 'server-only'
import crypto from 'crypto'
import fs     from 'fs'
import path   from 'path'

/**
 * encryptionKey.ts
 * Location: app/lib/encryptionKey.ts
 *
 * The ONE place that knows the server's encryption key and how to encrypt
 * with it (AES-256-GCM). The key is a random 32-byte secret (64 hex
 * characters) in NXF_ENCRYPTION_KEY, generated by the installer.
 *
 * There is NO fallback: if the key is missing or malformed, encrypting
 * throws. Never derive a key from row ids or other non-secret values.
 *
 * During install, /api/save-config runs before Next.js has reloaded
 * .env.local, so when process.env does not have the key yet it is read from
 * the .env.local file on disk.
 */

const IV_LENGTH = 16
const KEY_VAR   = 'NXF_ENCRYPTION_KEY'
const HEX_64    = /^[0-9a-fA-F]{64}$/

function readKeyFromEnvFile(): string | null {
  try {
    const text = fs.readFileSync(path.resolve(process.cwd(), '.env.local'), 'utf-8')
    const line = text.split(/\r?\n/).find((l) => l.startsWith(`${KEY_VAR}=`))
    if (!line) return null
    return line.slice(KEY_VAR.length + 1).trim().replace(/^["']|["']$/g, '')
  } catch {
    return null
  }
}

/** Returns the 32-byte encryption key, or throws if it is not configured. */
export function getEncryptionKey(): Buffer {
  const raw = process.env[KEY_VAR] || readKeyFromEnvFile()

  if (!raw || !HEX_64.test(raw)) {
    throw new Error(
      `${KEY_VAR} is missing or invalid (needs 64 hex characters). ` +
      `Run the installer, or add it to .env.local.`
    )
  }

  return Buffer.from(raw, 'hex')
}

/** Encrypts any JSON-serialisable value. Returns hex iv, content and auth tag. */
export function encryptJson(data: any): { iv: string; content: string; tag: string } {
  const key    = getEncryptionKey()
  const iv     = crypto.randomBytes(IV_LENGTH)
  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv)

  const encrypted = Buffer.concat([
    cipher.update(JSON.stringify(data), 'utf8'),
    cipher.final(),
  ])

  return {
    iv:      iv.toString('hex'),
    content: encrypted.toString('hex'),
    tag:     cipher.getAuthTag().toString('hex'),
  }
}